import { ark } from "@ark-ui/react";
import { createFormHook, createFormHookContexts } from "@tanstack/react-form";
import { Check, ChevronDown } from "lucide-react";
import { useMemo } from "react";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/thornberry/components/button";
import {
  CheckboxControl,
  CheckboxHiddenInput,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxRoot,
} from "@/registry/thornberry/components/checkbox";
import { Input } from "@/registry/thornberry/components/input";
import {
  Select,
  SelectContent,
  SelectControl,
  SelectHiddenSelect,
  SelectIndicator,
  SelectItem,
  SelectItemIndicator,
  SelectItemText,
  SelectLabel,
  SelectPositioner,
  SelectTrigger,
  SelectValueText,
  createListCollection,
} from "@/registry/thornberry/components/select";

import type { ComponentProps, ReactNode } from "react";

/**
 * TanStack Form wrapper for thornberry.
 *
 * Uses the TanStack Form composition API (`createFormHook`) to pre-bind a set
 * of field components onto thornberry's own inputs, so consumers get typed,
 * validation-aware fields with matching styling out of the box.
 *
 * @example
 * const form = useAppForm({
 *   defaultValues: { name: "", role: "coach", active: true, bio: "" },
 *   onSubmit: async ({ value }) => save(value),
 * });
 *
 * <form
 *   onSubmit={(e) => {
 *     e.preventDefault();
 *     form.handleSubmit();
 *   }}
 * >
 *   <form.AppField name="name">
 *     {(field) => <field.TextField label="Name" />}
 *   </form.AppField>
 *   <form.AppField name="role">
 *     {(field) => (
 *       <field.SelectField
 *         label="Role"
 *         items={[
 *           { label: "Coach", value: "coach" },
 *           { label: "Admin", value: "admin" },
 *         ]}
 *       />
 *     )}
 *   </form.AppField>
 *   <form.AppField name="active">
 *     {(field) => <field.CheckboxField label="Active" />}
 *   </form.AppField>
 *   <form.AppField name="bio">
 *     {(field) => <field.TextareaField label="Bio" />}
 *   </form.AppField>
 *   <form.AppForm>
 *     <form.SubmitButton label="Save" />
 *   </form.AppForm>
 * </form>;
 */
const { fieldContext, formContext, useFieldContext, useFormContext } =
  createFormHookContexts();

/**
 * Normalize the heterogeneous TanStack error array (strings from function
 * validators, `{ message }` objects from standard-schema validators) into a
 * flat list of human-readable strings.
 */
const errorMessages = (errors: unknown[]): string[] =>
  errors
    .map((error) =>
      typeof error === "string"
        ? error
        : ((error as { message?: string } | null)?.message ?? ""),
    )
    .filter(Boolean);

const FieldErrors = ({ errors }: { errors: unknown[] }) => {
  const messages = errorMessages(errors);

  if (!messages.length) return null;

  return (
    <p className="font-medium text-destructive text-xs">
      {messages.join(", ")}
    </p>
  );
};

const FieldLabel = ({
  htmlFor,
  children,
}: {
  htmlFor?: string;
  children: ReactNode;
}) => (
  <label
    htmlFor={htmlFor}
    className="font-medium text-sm leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
  >
    {children}
  </label>
);

interface TextFieldProps
  extends Omit<
    ComponentProps<typeof Input>,
    "value" | "onChange" | "onBlur" | "name"
  > {
  label?: string;
}

const TextField = ({ label, className, id, ...rest }: TextFieldProps) => {
  const field = useFieldContext<string>();
  const fieldId = id ?? field.name;
  const hasError =
    field.state.meta.isTouched && field.state.meta.errors.length > 0;

  return (
    <div className="flex w-full flex-col gap-1.5">
      {label && <FieldLabel htmlFor={fieldId}>{label}</FieldLabel>}
      <Input
        id={fieldId}
        name={field.name}
        value={field.state.value ?? ""}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(event.target.value)}
        aria-invalid={hasError || undefined}
        className={cn(
          hasError && "border-destructive focus-visible:ring-destructive",
          className,
        )}
        {...rest}
      />
      {hasError && <FieldErrors errors={field.state.meta.errors} />}
    </div>
  );
};

interface TextareaFieldProps
  extends Omit<
    ComponentProps<typeof ark.textarea>,
    "value" | "onChange" | "onBlur" | "name"
  > {
  label?: string;
}

const TextareaField = ({
  label,
  className,
  id,
  ...rest
}: TextareaFieldProps) => {
  const field = useFieldContext<string>();
  const fieldId = id ?? field.name;
  const hasError =
    field.state.meta.isTouched && field.state.meta.errors.length > 0;

  return (
    <div className="flex w-full flex-col gap-1.5">
      {label && <FieldLabel htmlFor={fieldId}>{label}</FieldLabel>}
      <ark.textarea
        id={fieldId}
        name={field.name}
        value={field.state.value ?? ""}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(event.target.value)}
        aria-invalid={hasError || undefined}
        className={cn(
          "flex min-h-16 w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm transition-colors placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary disabled:cursor-not-allowed disabled:opacity-50",
          hasError && "border-destructive focus-visible:ring-destructive",
          className,
        )}
        {...rest}
      />
      {hasError && <FieldErrors errors={field.state.meta.errors} />}
    </div>
  );
};

interface CheckboxFieldProps {
  label?: string;
}

const CheckboxField = ({ label }: CheckboxFieldProps) => {
  const field = useFieldContext<boolean>();
  const hasError =
    field.state.meta.isTouched && field.state.meta.errors.length > 0;

  return (
    <div className="flex flex-col gap-1.5">
      <CheckboxRoot
        checked={field.state.value ?? false}
        onCheckedChange={(details) =>
          field.handleChange(details.checked === true)
        }
      >
        <CheckboxControl>
          <CheckboxIndicator>
            <Check className="size-3.5" />
          </CheckboxIndicator>
        </CheckboxControl>
        {label && <CheckboxLabel>{label}</CheckboxLabel>}
        <CheckboxHiddenInput />
      </CheckboxRoot>
      {hasError && <FieldErrors errors={field.state.meta.errors} />}
    </div>
  );
};

interface SelectFieldItem {
  label: string;
  value: string;
}

interface SelectFieldProps {
  label?: string;
  items: SelectFieldItem[];
  placeholder?: string;
}

const SelectField = ({ label, items, placeholder }: SelectFieldProps) => {
  const field = useFieldContext<string>();
  const hasError =
    field.state.meta.isTouched && field.state.meta.errors.length > 0;
  const collection = useMemo(() => createListCollection({ items }), [items]);

  return (
    <div className="flex w-full flex-col gap-1.5">
      <Select
        collection={collection}
        value={field.state.value ? [field.state.value] : []}
        onValueChange={(details) => field.handleChange(details.value[0] ?? "")}
        onInteractOutside={() => field.handleBlur()}
      >
        {label && (
          <SelectLabel className="text-foreground">{label}</SelectLabel>
        )}
        <SelectControl>
          <SelectTrigger
            className={cn(
              "w-full border border-input bg-transparent",
              hasError && "border-destructive",
            )}
          >
            <SelectValueText placeholder={placeholder ?? "Select an option"} />
            <SelectIndicator>
              <ChevronDown className="size-4 opacity-50" />
            </SelectIndicator>
          </SelectTrigger>
        </SelectControl>
        <SelectPositioner>
          <SelectContent>
            {collection.items.map((item) => (
              <SelectItem key={item.value} item={item}>
                <SelectItemText>{item.label}</SelectItemText>
                <SelectItemIndicator />
              </SelectItem>
            ))}
          </SelectContent>
        </SelectPositioner>
        <SelectHiddenSelect />
      </Select>
      {hasError && <FieldErrors errors={field.state.meta.errors} />}
    </div>
  );
};

interface SubmitButtonProps
  extends Omit<ComponentProps<typeof Button>, "type"> {
  label: string;
}

const SubmitButton = ({ label, ...rest }: SubmitButtonProps) => {
  const form = useFormContext();

  return (
    <form.Subscribe
      selector={(state) => ({
        canSubmit: state.canSubmit,
        isSubmitting: state.isSubmitting,
      })}
    >
      {({ canSubmit, isSubmitting }) => (
        <Button type="submit" disabled={!canSubmit} {...rest}>
          {isSubmitting ? "Submitting..." : label}
        </Button>
      )}
    </form.Subscribe>
  );
};

const { useAppForm, withForm, withFieldGroup } = createFormHook({
  fieldContext,
  formContext,
  fieldComponents: {
    TextField,
    TextareaField,
    CheckboxField,
    SelectField,
  },
  formComponents: {
    SubmitButton,
  },
});

export {
  useAppForm,
  withForm,
  withFieldGroup,
  useFieldContext,
  useFormContext,
  fieldContext,
  formContext,
  TextField,
  TextareaField,
  CheckboxField,
  SelectField,
  SubmitButton,
  type TextFieldProps,
  type TextareaFieldProps,
  type CheckboxFieldProps,
  type SelectFieldProps,
  type SelectFieldItem,
  type SubmitButtonProps,
};

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

import type { ClassValue } from "clsx";

export const cn = (...inputs: ClassValue[]) => {
  return twMerge(clsx(inputs));
};

import { ark } from "@ark-ui/react";
import { cva } from "class-variance-authority";

import { cn } from "@/lib/utils";

import type { VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";

const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap outline-none focus-visible:outline-none focus-visible:ring-offset-background focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 rounded-md font-medium text-sm outline-hidden disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0 transition-[color,box-shadow,transform]",
  {
    variants: {
      variant: {
        solid:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground",
        muted: "bg-muted text-muted-foreground shadow-xs hover:bg-muted/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-2 hover:underline",
        destructive:
          "bg-destructive text-background shadow-xs hover:bg-destructive/90 focus-visible:ring-red-500 aria-invalid:ring-red-500/20 dark:aria-invalid:ring-red-500/40",
        // no-style escape hatch: render the bare element and style it via
        // className (widely used downstream for icon/link-like buttons)
        unstyled: "",
      },
      size: {
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        md: "h-9 px-4 py-2 has-[>svg]:px-3",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "solid",
      size: "md",
    },
  },
);

const Button = ({
  className,
  variant,
  size,
  ...rest
}: ComponentProps<typeof ark.button> & VariantProps<typeof buttonVariants>) => (
  <ark.button
    type="button"
    className={cn(buttonVariants({ variant, size }), className)}
    {...rest}
  />
);

export { Button, buttonVariants };

