  <div
    className={cn("pointer-events-none -mx-1 my-1 h-px bg-border", className)}
    {...rest}
  />
);

export {
  Select,
  SelectRoot,
  SelectRootProvider,
  SelectContext,
  SelectLabel,
  SelectControl,
  SelectTrigger,
  SelectValueText,
  SelectIndicator,
  SelectClearTrigger,
  SelectPositioner,
  SelectContent,
  SelectItemGroup,
  SelectItemGroupLabel,
  SelectItem,
  SelectItemText,
  SelectItemIndicator,
  SelectSeparator,
  SelectHiddenSelect,
};

// Re-export createListCollection for convenience
export { createListCollection } from "@ark-ui/react";
